<?php
namespace Tests;
use App\Services\{BulkGateSms,SmsDeliveryException,SalonStore,Notifications,PlatformConnections};
use Carbon\CarbonImmutable as Time;
use Illuminate\Foundation\Testing\TestCase;
use Illuminate\Support\Facades\{Artisan,DB,Http,Crypt};
final class BulkGateSmsTest extends TestCase {
 private string $path;
 public function createApplication(){$a=require __DIR__.'/../bootstrap/app.php';$a->make(\Illuminate\Contracts\Console\Kernel::class)->bootstrap();return $a;}
 protected function setUp():void{parent::setUp();if(config('database.default')!=='sqlite'||config('database.connections.sqlite.database')!==':memory:')throw new \RuntimeException('In-memory test DB required');Artisan::call('migrate',['--force'=>true]);foreach(['salon_state','deliveries','providers','provider_security','provider_members'] as $t)DB::table($t)->delete();DB::table('salon_state')->insert(['id'=>1,'data'=>json_encode(SalonStore::initial())]);$this->path=storage_path('framework/bulkgate-test-'.bin2hex(random_bytes(6)));config(['operator.connections_path'=>$this->path,'integrations.path'=>$this->path.'-provider']);Time::setTestNow('2030-03-05T10:00:00Z');Http::preventStrayRequests();}
 protected function tearDown():void{foreach(glob($this->path.'*') as $f)if(is_file($f))unlink($f);Time::setTestNow();parent::tearDown();}
 private function keys():array{return ['bulkgate_application_id'=>'12345','bulkgate_application_token'=>'test-secret-not-in-logs','bulkgate_sender_type'=>'gSystem'];}
 private function accepted(){return Http::response(['data'=>['status'=>'accepted','sms_id'=>'sms-reference-1']]);}
 private function job():void{app(PlatformConnections::class)->save($this->keys());$b=['id'=>'test-sms','name'=>'Béla','phone'=>'06301234567','email'=>'','staff'=>'anna','start'=>now()->addDay()->toISOString(),'status'=>'confirmed','serviceSnapshot'=>[['name'=>'Hajvágás']],'token'=>str_repeat('a',64),'updatedAt'=>now()->toISOString()];app(SalonStore::class)->mutate(function(&$s)use($b){$s['settings']['notifyGuest']=true;$s['settings']['notifyProvider']=false;$s['settings']['channel']='sms';$s['settings']['reminderGuest']=false;$s['bookings']=[$b];});app(Notifications::class)->enqueue($b,app(SalonStore::class)->read(),'created');}
 public function test_request_is_transactional_normalized_unicode_and_deduplicated():void{Http::fake(['portal.bulkgate.com/*'=>$this->accepted()]);$id=app(BulkGateSms::class)->send('+36 (30) 123-4567','Időpont emlékeztető',$this->keys());$this->assertSame('sms-reference-1',$id);Http::assertSent(fn($r)=>$r->method()==='POST'&&$r->url()==='https://portal.bulkgate.com/api/1.0/simple/transactional'&&$r['number']==='36301234567'&&$r['unicode']===true&&$r['sender_id']==='gSystem'&&!isset($r['sender_id_value'])&&$r['duplicates_check']==='on'&&$r['application_id']===12345);}
 public function test_encoding_limits_and_sender_profile():void{$this->assertSame(['unicode'=>false,'units'=>8],BulkGateSms::encoding('Hi [X]'));$this->assertTrue(BulkGateSms::encoding('ő')['unicode']);$this->assertEquals(2,BulkGateSms::encoding('😀')['units']);Http::fake(['portal.bulkgate.com/*'=>$this->accepted()]);app(BulkGateSms::class)->send('06301234567','Test',array_replace($this->keys(),['bulkgate_sender_type'=>'gProfile','bulkgate_sender_value'=>'123']));Http::assertSent(fn($r)=>$r['unicode']===false&&$r['sender_id']==='gProfile'&&$r['sender_id_value']==='123');try{app(BulkGateSms::class)->send('06301234567',str_repeat('ő',269),$this->keys());$this->fail();}catch(SmsDeliveryException $e){$this->assertFalse($e->uncertain);}Http::assertSentCount(1);}
 public function test_booking_send_is_stored_once_and_legacy_twilio_is_not_used():void{$this->job();Http::fake(['portal.bulkgate.com/*'=>$this->accepted()]);$this->assertSame(1,app(Notifications::class)->run()['sent']);$this->assertSame('sent',DB::table('deliveries')->value('status'));$this->assertSame('sms-reference-1',DB::table('deliveries')->value('provider_reference'));app(Notifications::class)->run();Http::assertSentCount(1);}
 public function test_timeout_is_unknown_without_automatic_retry_or_token_leak():void{$this->job();$requests=0;Http::fake(function()use(&$requests){$requests++;throw new \Illuminate\Http\Client\ConnectionException('secret=test-secret-not-in-logs');});$this->assertSame(1,app(Notifications::class)->run()['failed']);$row=DB::table('deliveries')->first();$this->assertSame('unknown',$row->status);$this->assertStringNotContainsString('test-secret-not-in-logs',$row->error);Time::setTestNow(now()->addHour());app(Notifications::class)->run();$this->assertSame(1,$requests);}
 public function test_explicit_rejection_is_failed_but_rate_limit_can_retry():void{$this->job();$limited=true;Http::fake(function()use(&$limited){return $limited?Http::response(['error'=>'Too many requests'],429):$this->accepted();});app(Notifications::class)->run();$this->assertSame('pending',DB::table('deliveries')->value('status'));$limited=false;Time::setTestNow(now()->addMinutes(6));$this->assertSame(1,app(Notifications::class)->run()['sent']);Http::assertSentCount(2);}
 public function test_error_or_ambiguous_success_is_never_marked_sent():void{foreach([Http::response(['error'=>'token=test-secret-not-in-logs'],200),Http::response(['data'=>['status'=>'accepted']],200)] as $response){Http::fake(fn()=>$response);try{app(BulkGateSms::class)->send('06301234567','test',$this->keys());$this->fail('No accepted ID');}catch(SmsDeliveryException $e){$this->assertStringNotContainsString('test-secret-not-in-logs',$e->getMessage());}}}
 public function test_stale_sms_processing_is_not_automatically_resent():void{$this->job();DB::table('deliveries')->update(['status'=>'processing','locked_at'=>now()->subMinutes(11)]);app(Notifications::class)->run();$this->assertSame('unknown',DB::table('deliveries')->value('status'));Http::assertNothingSent();}
 public function test_unknown_retry_requires_explicit_confirmation():void{$this->job();DB::table('deliveries')->update(['status'=>'unknown']);$id=DB::table('deliveries')->value('id');$this->withSession(['admin'=>true,'provider_id'=>1,'_token'=>str_repeat('r',40)])->withHeader('X-CSRF-TOKEN',str_repeat('r',40));$this->postJson('/api/deliveries/'.$id.'/retry')->assertUnprocessable();$this->assertSame('unknown',DB::table('deliveries')->value('status'));$this->postJson('/api/deliveries/'.$id.'/retry',['confirmedNotSent'=>true])->assertOk();$this->assertSame('pending',DB::table('deliveries')->value('status'));Http::assertNothingSent();}
 public function test_gateway_migration_holds_old_sms_without_holding_email():void{$this->job();DB::table('deliveries')->insert(['provider_id'=>1,'dedup'=>'email-migration-test','payload'=>Crypt::encryptString(json_encode(['channel'=>'email'])),'status'=>'pending','attempts'=>0,'available_at'=>now(),'created_at'=>now(),'updated_at'=>now()]);$migration=require base_path('database/migrations/2026_11_12_000016_add_sms_provider_reference.php');$migration->up();$this->assertSame('on_hold',DB::table('deliveries')->where('dedup','!=','email-migration-test')->value('status'));$this->assertSame('pending',DB::table('deliveries')->where('dedup','email-migration-test')->value('status'));$migration->up();$this->assertSame(2,DB::table('deliveries')->count());Http::assertNothingSent();}
 public function test_credentials_are_private_preserved_and_provider_cannot_override():void{$this->withSession(['platform_admin'=>true,'_token'=>str_repeat('b',40)])->withHeader('X-CSRF-TOKEN',str_repeat('b',40));$this->putJson('/api/platform/connections',$this->keys())->assertOk();$this->putJson('/api/platform/connections',['bulkgate_application_token'=>''])->assertOk();$this->getJson('/api/platform/connections')->assertJsonPath('bulkgate_application_token_configured',true)->assertJsonMissingPath('bulkgate_application_token')->assertJsonMissingPath('twilio_sid');$this->assertSame($this->keys()['bulkgate_application_token'],app(PlatformConnections::class)->values()['bulkgate_application_token']);$this->withSession(['platform_admin'=>false,'admin'=>true,'provider_id'=>1]);$this->getJson('/api/connections')->assertOk()->assertJsonMissingPath('bulkgate_application_id')->assertJsonMissingPath('bulkgate_application_token_configured');$this->putJson('/api/connections',$this->keys())->assertForbidden();Http::assertNothingSent();}
}
